window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-30402bdd7c5492b5"]={"versions": [{"id": "FIG-30402bdd7c5492b5", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML 2.x Sequenzdiagramm (Interaktionsdiagramm) mit InteractionUse-Fragment (<code>ref</code>).</li>\n<li><strong>Architektur-Kontext:</strong> AUTOSAR Adaptive Platform (ARA), Release R20-11, spezifiziert im Dokument <em>AUTOSAR_EXP_SWArchitecture</em> (Kapitel 10.2).</li>\n<li><strong>Funktionaler Zweck:</strong> Modellierung des deterministischen, stufenweisen Herunterfahrens (Graceful Shutdown) der gesamten Adaptive Runtime Environment auf einer Machine. Das Diagramm definiert das Zusammenspiel zwischen Mode/State Management, Prozesslebenszyklus-Steuerung durch Execution Management (EM), Überwachungsdeaktivierung durch Platform Health Management (PHM) und dem finalen OS-/Hardware-Halt.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Akteure & Lifelines</p>\n<ul class=\"fig-list\">\n<li><strong><code>SM: State Management</code>:</strong> AUTOSAR Adaptive Functional Cluster (FC), steuert die Systemzustände (Machine States, Function Group States) anhand interner/externer Ereignisse.</li>\n<li><strong><code>EM: Execution Management</code>:</strong> Zentraler Plattform-FC und primärer POSIX-Init-/Lifecycle-Manager; kontrolliert Prozesszustände über den <code>ExecutionClient</code> und initiiert Prozess-Terminierungen sowie den Machine-Shutdown.</li>\n<li><strong><code>PHM: Platform Health Monitor</code>:</strong> FC zur funktionalen Sicherheits- und Zustandsüberwachung (Alive-, Deadline-, Logical-Supervision).</li>\n<li><strong><code>:Operating System</code>:</strong> POSIX-konformes Betriebssystem (Kernel, IPC, Signal- und Prozess-Subsystem).</li>\n<li><strong><code>:Watchdog Driver</code>:</strong> Treiber-/Hardware-Abstraktionsschicht zur Kontrolle und Deaktivierung des Plattform-/Hardware-Watchdogs.</li>\n</ul>\n<p class=\"fig-p\">#### Schnittstellen & Interaktionsprimitive</p>\n<ul class=\"fig-list\">\n<li><strong><code>event()</code>:</strong> Asynchroner Trigger (z. B. Klemme 15 / Ignition-Off, Diagnoseanforderung <code>ECUReset</code>, Power-Management-Event) an SM.</li>\n<li><strong><code>ref Function Group State Transition(Shutdown)</code>:</strong> Referenzierte Interaktionssequenz zur Überführung aller Function Groups der Applikations- und Plattformebene in den Zustand <code>Off</code>/<code>Shutdown</code>.</li>\n<li><strong><code>TerminateProcess(...)</code>:</strong> OS-spezifische Signalisierung (typischerweise <code>SIGTERM</code>) initiiert durch EM zur geordneten Beendigung eines Prozesses.</li>\n<li><strong><code>ReportExecutionState(terminating): Result</code>:</strong> API des <code>ara::exec::ExecutionClient</code> (<code>ReportExecutionState(ara::exec::ExecutionState::kTerminating)</code>), mit dem sich ein Prozess synchron/asynchron vor dem Exit bei EM als terminierend registriert.</li>\n<li><strong><code>ProcessChanged(terminating, SM)</code>:</strong> EM-interner Zustandsübergang zur Nachverfolgung der Prozesszustandsänderung.</li>\n<li><strong><code>Disable()</code>:</strong> Kontrollierter Deaktivierungsaufruf an den <code>:Watchdog Driver</code>, um unbeabsichtigte Watchdog-Resets während der verbleibenden Shutdown-Phase zu verhindern.</li>\n<li><strong><code>Shutdown()</code>:</strong> Niederpriores OS-Systemkommando (z. B. <code>sync()</code>, gefolgt von <code>reboot(RB_POWER_OFF)</code> oder Power-Controller-Shutdown), aufgerufen durch EM.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Shutdown-Initiierung & Applikationsdrain:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Eintreffen von <code>event()</code> am <code>SM</code>.</li>\n<li>Eintritt in das Interaktionsfragment <code>Function Group State Transition(Shutdown)</code>: EM beendet deterministisch alle regulären Applikations- und Plattformprozesse in definierter Reihenfolge (im Diagramm aus Platzgründen abstrahiert). Anschließend wird der Machine State <code>Shutdown</code> angefordert.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Phase 1: Terminierung von State Management (SM):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>EM ruft über das Betriebssystem <code>TerminateProcess(SM)</code> auf (<code>SIGTERM</code>).</li>\n<li>Das Betriebssystem leitet das Terminierungssignal an den SM-Prozess weiter.</li>\n<li>SM führt flüchtige Aufräumarbeiten durch und meldet <code>ReportExecutionState(terminating)</code> via <code>ExecutionClient</code> an EM zurück.</li>\n<li>EM quittiert/verarbeitet dies intern (<code>ProcessChanged(terminating, SM)</code>).</li>\n<li>SM-Prozess terminiert vollständig (gekennzeichnet durch das Lebenslinien-Endkreuz <code>X</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Phase 2: Terminierung von Platform Health Management (PHM) & Watchdog-Stopp:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>EM initiiert <code>TerminateProcess(PHM)</code> über das OS.</li>\n<li>OS signalisiert PHM die Terminierung.</li>\n<li><strong>Kritischer Schritt:</strong> PHM deaktiviert explizit den Hardware-Watchdog via <code>Disable()</code> am <code>:Watchdog Driver</code>. Damit wird verhindert, dass fehlende Servicing-Events während des OS-Sync/Power-Down zu einem unkontrollierten Watchdog-Reset führen.</li>\n<li>PHM meldet <code>ReportExecutionState(terminating)</code> an EM.</li>\n<li>PHM-Prozess terminiert vollständig (<code>X</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Phase 3: Finaler Betriebssystem-Shutdown:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>EM führt interne Aufräumarbeiten durch (Flush eigener Puffer, Deregistrierung von OS-Ressourcen).</li>\n<li>EM sendet <code>Shutdown()</code> an das <code>:Operating System</code>.</li>\n<li>EM beendet seine eigene Ausführung (<code>X</code>); das OS trennt Dateisysteme/Caches (<code>sync</code>) und fährt die CPU/Spannungsversorgung herunter.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong><code>ExecutionClient</code>-Meldevertrag (<code>kTerminating</code>):</strong> Jeder Adaptive-Prozess (Plattform- und Standard-Applikationen) muss zwingend <code>ara::exec::ExecutionClient::ReportExecutionState(ara::exec::ExecutionState::kTerminating)</code> aufrufen, sobald er das OS-Terminierungssignal empfängt. Erfolgt diese Rückmeldung nicht innerhalb des manifestierten <code>terminationTimeout</code> im Execution-Manifest, erzwingt EM die Terminierung via <code>SIGKILL</code> (Non-graceful termination).</li>\n<li><strong>Shutdown-Hierarchie & Abhängigkeiten:</strong></li>\n<li>Standard-Applikationen werden vor den zentralen Kontroll-Dämonen beendet.</li>\n<li>SM steuert den Gesamtprozess, wird aber vor PHM terminiert.</li>\n<li>PHM muss bis zuletzt aktiv bleiben, um die Supervision der Plattformprozesse aufrechtzuerhalten, muss aber zwingend vor EM terminieren und vor dem eigenen Exit den Watchdog entkoppeln.</li>\n<li><strong>Watchdog-Handling im BSP/Treiber:</strong> Der <code>:Watchdog Driver</code> muss eine Deaktivierungs-Schnittstelle (<code>Disable()</code>) bereitstellen oder in einen unkritischen Modus wechseln, da nach der PHM-Terminierung kein zyklisches Triggern (Watchdog Servicing) mehr erfolgt.</li>\n<li><strong>Persistenz & Ressourcenfreigabe:</strong> Da der Übergang <code>Function Group State Transition(Shutdown)</code> vor der Terminierung der Core-Dienste erfolgt, müssen alle NvM-Schreibvorgänge (<code>ara::per</code>), Kommunikationskanäle (<code>ara::com</code>) und Socket-Verbindungen innerhalb des referenzierten Fragments abgeschlossen sein. Während des SM/PHM/EM-Shutdowns stehen keine IPC-/ARA-Dienste für Applikationen mehr zur Verfügung.</li>\n</ul>"}, {"id": "FIG-156e67a3d3290c27", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML 2.x Sequenzdiagramm (Interaktionsdiagramm) mit InteractionUse-Fragment (<code>ref</code>).</li>\n<li><strong>Architektur-Kontext:</strong> AUTOSAR Adaptive Platform (ARA), Release R21-11, spezifiziert im Dokument <em>AUTOSAR_EXP_SWArchitecture</em> (Kapitel 10.2).</li>\n<li><strong>Funktionaler Zweck:</strong> Modellierung des deterministischen, stufenweisen Herunterfahrens (Graceful Shutdown) der gesamten Adaptive Runtime Environment auf einer Machine. Das Diagramm definiert das Zusammenspiel zwischen Mode/State Management, Prozesslebenszyklus-Steuerung durch Execution Management (EM), Überwachungsdeaktivierung durch Platform Health Management (PHM) und dem finalen OS-/Hardware-Halt.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Akteure & Lifelines</p>\n<ul class=\"fig-list\">\n<li><strong><code>SM: State Management</code>:</strong> AUTOSAR Adaptive Functional Cluster (FC), steuert die Systemzustände (Machine States, Function Group States) anhand interner/externer Ereignisse.</li>\n<li><strong><code>EM: Execution Management</code>:</strong> Zentraler Plattform-FC und primärer POSIX-Init-/Lifecycle-Manager; kontrolliert Prozesszustände über den <code>ExecutionClient</code> und initiiert Prozess-Terminierungen sowie den Machine-Shutdown.</li>\n<li><strong><code>PHM: Platform Health Management</code>:</strong> FC zur funktionalen Sicherheits- und Zustandsüberwachung (Alive-, Deadline-, Logical-Supervision).</li>\n<li><strong><code>:Operating System</code>:</strong> POSIX-konformes Betriebssystem (Kernel, IPC, Signal- und Prozess-Subsystem).</li>\n<li><strong><code>:WatchdogInterface</code>:</strong> Schnittstelle bzw. Hardware-Abstraktionsschicht zur Kontrolle und Deaktivierung des Plattform-/Hardware-Watchdogs.</li>\n</ul>\n<p class=\"fig-p\">#### Schnittstellen & Interaktionsprimitive</p>\n<ul class=\"fig-list\">\n<li><strong><code>event()</code>:</strong> Asynchroner Trigger (z. B. Klemme 15 / Ignition-Off, Diagnoseanforderung <code>ECUReset</code>, Power-Management-Event) an SM.</li>\n<li><strong><code>ref Function Group State Transition(Shutdown)</code>:</strong> Referenzierte Interaktionssequenz zur Überführung aller Function Groups der Applikations- und Plattformebene in den Zustand <code>Off</code>/<code>Shutdown</code>.</li>\n<li><strong><code>TerminateProcess(...)</code>:</strong> OS-spezifische Signalisierung (typischerweise <code>SIGTERM</code>) initiiert durch EM zur geordneten Beendigung eines Prozesses.</li>\n<li><strong><code>ReportExecutionState(terminating): Result</code>:</strong> API des <code>ara::exec::ExecutionClient</code> (<code>ReportExecutionState(ara::exec::ExecutionState::kTerminating)</code>), mit dem sich ein Prozess synchron/asynchron vor dem Exit bei EM als terminierend registriert.</li>\n<li><strong><code>Disable()</code>:</strong> Kontrollierter Deaktivierungsaufruf an <code>:WatchdogInterface</code>, um unbeabsichtigte Watchdog-Resets während der verbleibenden Shutdown-Phase zu verhindern.</li>\n<li><strong><code>Shutdown()</code>:</strong> Niederpriores OS-Systemkommando (z. B. <code>sync()</code>, gefolgt von <code>reboot(RB_POWER_OFF)</code> oder Power-Controller-Shutdown), aufgerufen durch EM.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Shutdown-Initiierung & Applikationsdrain:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Eintreffen von <code>event()</code> am <code>SM</code>.</li>\n<li>Eintritt in das Interaktionsfragment <code>Function Group State Transition(Shutdown)</code>: EM beendet deterministisch alle regulären Applikations- und Plattformprozesse in definierter Reihenfolge (im Diagramm aus Platzgründen abstrahiert). Anschließend wird der Machine State <code>Shutdown</code> angefordert.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Phase 1: Terminierung von State Management (SM):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>EM ruft über das Betriebssystem <code>TerminateProcess(SM)</code> auf (<code>SIGTERM</code>).</li>\n<li>Das Betriebssystem leitet das Terminierungssignal an den SM-Prozess weiter.</li>\n<li>SM führt flüchtige Aufräumarbeiten durch und meldet <code>ReportExecutionState(terminating): Result</code> zurück an EM.</li>\n<li>Der Lebenszyklus von SM endet (Zerstörung der Lifeline).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Phase 2: Terminierung von Platform Health Management (PHM) & Watchdog-Deaktivierung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>EM ruft über das Betriebssystem <code>TerminateProcess(PHM)</code> auf.</li>\n<li>Das Betriebssystem signalisiert PHM die Beendigung.</li>\n<li>PHM deaktiviert vor dem Beenden den Hardware-/Plattform-Watchdog über den Aufruf <code>Disable()</code> an <code>:WatchdogInterface</code>.</li>\n<li>PHM meldet <code>ReportExecutionState(terminating): Result</code> an EM zurück und beendet sich (Zerstörung der Lifeline).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Phase 3: Machine-Shutdown:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Nach Erhalt der Terminierungsbestätigung von PHM veranlasst EM den finalen Maschinenhalt durch den Systemaufruf <code>Shutdown()</code> an <code>:Operating System</code>.</li>\n<li>EM führt interne Aufräumroutinen durch (Self-Message / interner Loop) und beendet sich.</li>\n<li>Das Betriebssystem schaltet das Steuergerät ab bzw. versetzt die Hardware in den stromlosen/Reset-Zustand.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong><code>ExecutionClient</code>-Meldevertrag (<code>kTerminating</code>):</strong> Jeder Adaptive-Prozess (Plattform- und Standard-Applikationen) muss zwingend <code>ara::exec::ExecutionClient::ReportExecutionState(ara::exec::ExecutionState::kTerminating)</code> aufrufen, sobald er das OS-Terminierungssignal empfängt. Erfolgt diese Rückmeldung nicht innerhalb des manifestierten <code>terminationTimeout</code> im Execution-Manifest, erzwingt EM die Terminierung via <code>SIGKILL</code> (Non-graceful termination).</li>\n<li><strong>Shutdown-Hierarchie & Abhängigkeiten:</strong></li>\n<li>Standard-Applikationen werden vor den zentralen Kontroll-Dämonen beendet.</li>\n<li>SM steuert den Gesamtprozess, wird aber vor PHM terminiert.</li>\n<li>PHM muss bis zuletzt aktiv bleiben, um die Supervision der Plattformprozesse aufrechtzuerhalten, muss aber zwingend vor EM terminieren und vor dem eigenen Exit den Watchdog entkoppeln.</li>\n<li><strong>Watchdog-Handling im BSP/Treiber:</strong> Der <code>:Watchdog Driver</code> muss eine Deaktivierungs-Schnittstelle (<code>Disable()</code>) bereitstellen oder in einen unkritischen Modus wechseln, da nach der PHM-Terminierung kein zyklisches Triggern (Watchdog Servicing) mehr erfolgt.</li>\n<li><strong>Persistenz & Ressourcenfreigabe:</strong> Da der Übergang <code>Function Group State Transition(Shutdown)</code> vor der Terminierung der Core-Dienste erfolgt, müssen alle NvM-Schreibvorgänge (<code>ara::per</code>), Kommunikationskanäle (<code>ara::com</code>) und Socket-Verbindungen innerhalb des referenzierten Fragments abgeschlossen sein. Während des SM/PHM/EM-Shutdowns stehen keine IPC-/ARA-Dienste für Applikationen mehr zur Verfügung.</li>\n</ul>"}], "trans": [{"from": "FIG-30402bdd7c5492b5", "to": "FIG-156e67a3d3290c27", "fr": "R20-11", "tr": "R21-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><strong>Komponenten / Lifelines:</strong></li>\n<li><code>PHM: Platform Health Monitor</code> wurde umbenannt in <code>PHM: Platform Health Management</code>.</li>\n<li><code>:Watchdog Driver</code> (blau hinterlegt) wurde umbenannt in <code>:WatchdogInterface</code> (im Standardfarbton der übrigen Entitäten).</li>\n<li><strong>Ablauf & Interaktionen:</strong></li>\n<li>Der interne EM-Aufruf <code>ProcessChanged(terminating, SM)</code> an sich selbst entfällt vollständig.</li>\n<li>Das Signal <code>TerminateProcess(PHM)</code> wird nun direkt im Anschluss an den Empfang von <code>ReportExecutionState(terminating): Result</code> von SM ausgelöst.</li>\n<li>Bei den Aufrufen <code>TerminateProcess</code>, <code>ReportExecutionState</code>, <code>Disable</code> und <code>Shutdown</code> wurden die Parameter bzw. Klammern layoutseitig auf eigene Zeilen umgebrochen.</li>\n</ul>"}]};
